"use client";

import { useEffect,useMemo,useRef,useState } from "react";
import type { SupabaseClient } from "@supabase/supabase-js";
import { AlertTriangle,Ban,CalendarDays,CheckCircle2,Clock3,Copy,Edit3,Gauge,Plane,Plus,ShieldAlert,Trash2,Wind,Wrench,X } from "lucide-react";
import { editableOccurrences, flightToDraft, planFlightEdit, planFlightAction, recurrenceKey, recurrenceLabel, type FlightAction, type FlightScope } from "@/lib/coordination-edit";
import { operationalWaves } from "@/lib/coordination-waves";
import { ClientManagement } from "@/components/client-management";

type FuelUnit="L"|"lb"|"kg";
type CheckValue="pending"|"ok"|"no";
export type CoordinatedFlight={spot?:string;maintenancePostId?:string;id:string;prefix:string;model:string;base:string;date:string;departure:string;destination?:string;duration:number;fuelAmount:number;fuelUnit:FuelUnit;fuel:CheckValue;preflight:CheckValue;hums:CheckValue;engineStart:CheckValue;shutdown:CheckValue;revision:number;acknowledged:Record<string,number>;createdBy:string;updatedBy:string;planningStatus?:"planned"|"confirmed";wave?:number;commander?:string;copilot?:string;flightAttendant?:string;recurrenceLabel?:string;recurrenceId?:string;operationStartedAt?:string;operationEndedAt?:string;actualEngineStart?:string|null;actualShutdown?:string|null;cancelled?:boolean;cancelledAt?:string;cancellationReason?:string;deletedAt?:string;deletedBy?:string;actionBy?:Record<string,string>;history?:{field:string;value:string;employeeNumber:string;at:string}[]};
type Aircraft={prefix:string;model:string;base:string;available?:boolean};
type Person={employeeNumber:string;name:string;profile?:string};
type PlatformOption={id:string;name:string;clientName:string};
export type Draft={spot?:string;id:string;prefix:string;date:string;departure:string;destination:string;duration:string;fuelAmount:string;fuelUnit:FuelUnit;commander:string;copilot:string;flightAttendant:string;repeat:boolean;weekdays:number[];weekdayTimes:Record<number,string>};

const weekdayLabels=["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"];
const uid=()=>crypto.randomUUID();
const today=()=>{const date=new Date();return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;};
const clockToDuration=(value:string)=>{const [hours,minutes]=value.split(":").map(Number);return (hours*60+minutes)/60;};
const isS92=(model:string)=>model.toUpperCase().replace(/[^A-Z0-9]/g,"").includes("S92");
const addDays=(date:string,days:number)=>{const value=new Date(`${date}T12:00:00`);value.setDate(value.getDate()+days);return value.toISOString().slice(0,10);};

type MaintenanceAction={flightId?:string;spot?:string;crewRequirement?:string;commander?:string;copilot?:string;editedAt?:string;editedBy?:string;id:string;prefix?:string;title?:string;description?:string;category?:string;status?:string;createdAt?:string;priority?:string};

export function CoordinationDashboard({people=[],supabase,flights,aircraft,onOpenTrail,onOpenPlanning,onOpenAircraftManagement,onOpenWaves,onError}:{people?:{employeeNumber:string;name:string}[];supabase:SupabaseClient|null;flights:CoordinatedFlight[];aircraft:Aircraft[];onOpenTrail:(flight:CoordinatedFlight)=>void;onOpenPlanning:()=>void;onOpenAircraftManagement:()=>void;onOpenWaves:(date:string)=>void;onError:(message:string)=>void}){
 const [maintenance,setMaintenance]=useState<MaintenanceAction[]>([]);
 const [drying,setDrying]=useState<{id:string;prefix:string;model:string;base:string;reason:string;triggered_at:string}[]>([]);
 useEffect(()=>{if(!supabase)return;let active=true;const load=async()=>{const {data,error}=await supabase.from("compressor_drying_tasks").select("id,prefix,model,base,reason,triggered_at").eq("status","pending").order("triggered_at",{ascending:true});if(error){onError(`Fila de secagens indisponível: ${error.message}`);return;}if(active)setDrying(data??[]);};void load();const channel=supabase.channel("coordination-compressor-drying").on("postgres_changes",{event:"*",schema:"public",table:"compressor_drying_tasks"},()=>void load()).subscribe();return()=>{active=false;void supabase.removeChannel(channel);};},[supabase,onError]);
 const [focus,setFocus]=useState<"available"|"flying"|"upcoming"|"planned"|"alerts"|"maintenance"|"unavailable"|"cancelled"|"finished"|"drying">("available");
 const dryingSection=useRef<HTMLElement>(null);
 const [maintenanceCategory,setMaintenanceCategory]=useState("");
 const [clientsOpen,setClientsOpen]=useState(false);
 const currentDate=today();
 const [planningDate,setPlanningDate]=useState(currentDate);
 useEffect(()=>{if(!supabase)return;let active=true;const load=async()=>{const {data,error}=await supabase.rpc("list_maintenance_operation_cards");if(error){onError(error.message);return;}if(!active)return;setMaintenance(((data??[]) as MaintenanceAction[]).filter(item=>item.status!=="completed"));};const refresh=()=>void load();const timer=window.setInterval(refresh,15000);window.addEventListener("focus",refresh);void load();const channel=supabase.channel("coordination-dashboard-maintenance").on("postgres_changes",{event:"*",schema:"public",table:"shared_app_state"},refresh).subscribe();return()=>{active=false;window.clearInterval(timer);window.removeEventListener("focus",refresh);void supabase.removeChannel(channel);};},[supabase,currentDate,onError]);
 const todays=useMemo(()=>flights.filter((flight)=>!flight.maintenancePostId&&!flight.deletedAt&&flight.date===currentDate),[flights,currentDate]);
 const status=(flight:CoordinatedFlight)=>flight.cancelled?"cancelled":flight.planningStatus==="planned"?"planned":flight.actualShutdown||flight.shutdown==="ok"?"finished":flight.actualEngineStart||flight.engineStart==="ok"?"flying":"upcoming";
 const counts={finished:todays.filter((item)=>status(item)==="finished").length,cancelled:todays.filter((item)=>status(item)==="cancelled").length,available:aircraft.filter((item)=>item.available??true).length,unavailable:aircraft.filter((item)=>item.available===false).length,flying:todays.filter((item)=>status(item)==="flying").length,upcoming:todays.filter((item)=>status(item)==="upcoming").length,planned:todays.filter((item)=>status(item)==="planned").length,alerts:todays.filter((item)=>status(item)==="cancelled"||item.preflight==="no"||item.hums==="no"||item.fuel==="no").length,maintenance:maintenance.filter((item)=>!item.status||!["ok","resolved","closed"].includes(item.status)).length};
 const filtered=todays.filter((flight)=>focus==="maintenance"||focus==="unavailable"||focus==="available"?false:focus==="alerts"?status(flight)==="cancelled"||flight.preflight==="no"||flight.hums==="no"||flight.fuel==="no":status(flight)===focus);
 const byAircraft=aircraft.map((plane)=>({plane,items:filtered.filter((flight)=>flight.prefix===plane.prefix).sort((a,b)=>a.departure.localeCompare(b.departure))})).filter((group)=>focus==="unavailable"?group.plane.available===false:focus==="available"?group.plane.available!==false:group.items.length);
 const urgent=[...todays.filter((flight)=>status(flight)==="cancelled"||flight.preflight==="no"||flight.hums==="no"||flight.fuel==="no").map((flight)=>({id:flight.id,title:`${flight.prefix} · ${flight.destination||"Destino não informado"}`,detail:flight.cancelled?"Voo cancelado":"Verificação operacional com pendência",tone:"red",flight})),...maintenance.filter((item)=>item.priority==="urgent"||item.status==="no").map((item)=>({id:item.id,title:`${item.prefix??"Aeronave"} · ${item.title??"Manutenção"}`,detail:item.description??"Ação de manutenção requer atenção",tone:"amber",flight:null}))];
 const waves=useMemo(()=>operationalWaves(flights,planningDate),[flights,planningDate]);
 const maintenanceGroups=useMemo(()=>{const map=new Map<string,MaintenanceAction[]>();maintenance.filter((item)=>!item.status||!["ok","resolved","closed"].includes(item.status)).forEach((item)=>{const category=item.category||"Outros";map.set(category,[...(map.get(category)??[]),item]);});return [...map.entries()];},[maintenance]);
 const metricGroups=[
  {title:"Voos",columns:"sm:grid-cols-3 lg:grid-cols-5",items:[
   {key:"upcoming" as const,label:"Próximas saídas",value:counts.upcoming,icon:Clock3,tone:"text-sky-700 bg-sky-50"},
   {key:"planned" as const,label:"Aguardando confirmação",value:counts.planned,icon:CalendarDays,tone:"text-orange-700 bg-orange-50"},
   {key:"flying" as const,label:"Em andamento",value:counts.flying,icon:Gauge,tone:"text-blue-700 bg-blue-50"},
   {key:"finished" as const,label:"Voos finalizados",value:counts.finished,icon:CheckCircle2,tone:"text-green-700 bg-green-100"},
   {key:"cancelled" as const,label:"Voos cancelados",value:counts.cancelled,icon:Ban,tone:"text-red-700 bg-red-50"},
  ]},
  {title:"Aeronaves e manutenção",columns:"sm:grid-cols-3 lg:grid-cols-5",items:[
   {key:"available" as const,label:"Aeronaves disponíveis",value:counts.available,icon:Plane,tone:"text-blue-700 bg-blue-50"},
   {key:"unavailable" as const,label:"Indisponíveis",value:counts.unavailable,icon:ShieldAlert,tone:"text-red-700 bg-red-50"},
   {key:"alerts" as const,label:"Alertas operacionais",value:counts.alerts,icon:ShieldAlert,tone:"text-red-700 bg-red-50"},
   {key:"drying" as const,label:"Secagens de compressores",value:drying.length,icon:Wind,tone:"text-amber-700 bg-amber-50"},
   {key:"maintenance" as const,label:"Voos/giros de manutenção",value:counts.maintenance,icon:Wrench,tone:"text-violet-700 bg-violet-50"},
  ]},
 ];
 return <section className="space-y-5"><header className="flex items-center justify-between gap-4"><div><p className="text-xs font-extrabold uppercase tracking-[.16em] text-[#1769e0]">Centro de controle operacional</p><h2 className="text-2xl font-black text-[#17324d]">Visão geral da Coordenação</h2><p className="text-sm text-[#718197]">Voos, aeronaves, alertas e manutenção do dia em uma única visão.</p></div><div className="flex gap-2"><button onClick={()=>setClientsOpen(true)} className="hidden min-h-11 items-center gap-2 rounded-xl border border-[#1268d8] bg-white px-4 text-sm font-extrabold text-[#1268d8] lg:flex">Gestão de clientes</button><button onClick={onOpenAircraftManagement} className="hidden min-h-11 items-center gap-2 rounded-xl border border-[#1268d8] bg-white px-4 text-sm font-extrabold text-[#1268d8] lg:flex">Gestão de aeronaves</button><button onClick={onOpenPlanning} className="hidden min-h-11 items-center gap-2 rounded-xl bg-[#1268d8] px-4 text-sm font-extrabold text-white shadow-lg lg:flex"><Plus size={17}/>Programar voos</button></div></header>
 <div className="space-y-4">{metricGroups.map(group=><section key={group.title} aria-label={group.title}><h3 className="mb-2 text-xs font-extrabold uppercase tracking-wider text-[#52677f]">{group.title}</h3><div className={`grid grid-cols-2 gap-3 ${group.columns}`}>{group.items.map(({key,label,value,icon:Icon,tone})=><button key={key} aria-pressed={focus===key} onClick={()=>{setFocus(key);if(key==="drying"){dryingSection.current?.scrollIntoView({behavior:"smooth",block:"center"});dryingSection.current?.focus({preventScroll:true});}}} className={`min-h-32 rounded-2xl border p-4 text-left shadow-sm transition hover:-translate-y-0.5 ${focus===key?(key==="finished"?"border-green-600 ring-2 ring-green-100":"border-[#1268d8] ring-2 ring-blue-100"):key==="finished"?"border-green-200":"border-[#d9e4ef]"} ${key==="finished"?"bg-green-50":"bg-white"}`}><span className="mb-2 flex items-center justify-between gap-3"><strong className={`text-3xl ${key==="finished"?"text-green-800":"text-[#17324d]"}`}>{value}</strong><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${tone}`}><Icon size={18}/></span></span><span className="block text-xs font-bold leading-5 text-[#52677f]">{label}</span></button>)}</div></section>)}</div>
 <div className="grid gap-5 xl:grid-cols-[minmax(0,1.7fr)_minmax(320px,.8fr)]"><section className="rounded-2xl border border-[#d9e4ef] bg-white p-4 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-extrabold text-[#17324d]">{focus==="finished"?"Voos finalizados hoje":"Situação das aeronaves"}</h3><p className="text-xs text-[#718197]">{focus==="finished"?"Operações encerradas. Selecione um voo para ver os registros.":"Trilhos compactos em ordem de saída."}</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700">{filtered.length} movimentos</span></div><div className="max-h-[440px] space-y-2 overflow-y-auto pr-1">{focus==="finished"&&!filtered.length?<p className="p-8 text-center text-sm text-[#718197]">Nenhum voo finalizado hoje.</p>:null}{byAircraft.map(({plane,items})=><article key={plane.prefix} className="grid grid-cols-[100px_1fr] gap-3 rounded-xl border bg-[#f8fbfe] p-3"><div><strong className="font-mono text-[#17324d]">{plane.prefix}</strong><p className="text-[10px] text-[#718197]">{plane.model}</p></div><div className="flex gap-2 overflow-x-auto">{items.length?items.map((flight)=><button key={flight.id} onClick={()=>onOpenTrail(flight)} className={`min-w-36 rounded-lg border-l-4 p-2 text-left ${coordinationStatus(flight).card}`}><strong className="text-xs">{flight.departure} · {flight.destination||"Sem destino"}</strong><p className="mt-1 text-[10px] text-[#52677f]">{coordinationStatus(flight).label}</p>{flight.spot?<p className="mt-1 text-xs font-bold">Spot: {flight.spot}</p>:null}{focus==="finished"?<p className="mt-1 text-[10px] text-green-800">Encerramento: {flight.operationEndedAt?new Date(flight.operationEndedAt).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}):flight.actualShutdown||"Registrado"}</p>:null}{flight.recurrenceLabel?<p className="mt-1 text-[9px] font-bold text-violet-700">↻ Repetição ativa</p>:null}</button>):<span className="self-center text-xs text-[#9aabba]">Sem voo programado</span>}</div></article>)}</div></section>
 <section className="rounded-2xl border border-[#d9e4ef] bg-white p-4 shadow-sm"><div className="mb-4 flex items-center gap-2"><AlertTriangle className="text-amber-500" size={19}/><div><h3 className="font-extrabold text-[#17324d]">Agora · requer atenção</h3><p className="text-xs text-[#718197]">Pendências e impedimentos primeiro.</p></div></div><div className="max-h-[440px] space-y-2 overflow-y-auto">{urgent.map((item)=><button key={item.id} onClick={()=>item.flight&&onOpenTrail(item.flight)} className={`w-full rounded-xl border-l-4 p-3 text-left ${item.tone==="red"?"border-red-500 bg-red-50":"border-amber-500 bg-amber-50"}`}><strong className="text-sm text-[#17324d]">{item.title}</strong><p className="mt-1 text-xs text-[#657a90]">{item.detail}</p></button>)}{!urgent.length?<div className="rounded-xl border border-dashed p-8 text-center"><CheckCircle2 className="mx-auto text-emerald-500"/><p className="mt-2 text-sm font-bold">Nenhum alerta crítico agora</p></div>:null}</div></section></div>
 <section ref={dryingSection} tabIndex={-1} aria-label="Secagens de compressores pendentes" className="scroll-mt-6 rounded-2xl border border-amber-200 bg-amber-50 p-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-amber-300"><h4 className="font-extrabold text-amber-900">Secagens de compressores · {drying.length}</h4><p className="mt-1 text-xs text-amber-900">Lavagens confirmadas aguardando giro de secagem pelo piloto.</p><div className="mt-3 space-y-2">{drying.map(task=><article key={task.id} className="rounded-lg border border-amber-200 bg-white p-3"><strong className="font-mono">{task.prefix}</strong><p className="text-xs font-bold text-[#52677f]">{task.model} · {task.base}</p><p className="mt-1 text-xs">{task.reason}</p><p className="mt-1 text-xs text-[#718197]">Lavagem registrada: {new Date(task.triggered_at).toLocaleString("pt-BR")}</p><span className="mt-2 inline-block rounded-full bg-amber-100 px-2 py-1 text-xs font-bold text-amber-900">Aguardando secagem</span></article>)}{!drying.length?<p className="text-sm text-[#718197]">Nenhuma secagem pendente.</p>:null}</div></section>
 <div className="grid gap-5 xl:grid-cols-2"><WaveSummary groups={waves} date={planningDate} onDate={setPlanningDate} onOpen={()=>onOpenWaves(planningDate)}/>
 <section className="rounded-2xl border border-[#d9e4ef] bg-white p-4 shadow-sm"><h3 className="font-extrabold text-[#17324d]">Voos/giros de manutenção</h3><p className="mb-3 text-xs text-[#718197]">Categorias aparecem somente quando possuem ações abertas.</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{maintenanceGroups.map(([category,items])=><button key={category} onClick={()=>setMaintenanceCategory((current)=>current===category?"":category)} className={`rounded-xl border p-3 text-left ${maintenanceCategory===category?"border-violet-400 bg-violet-100 ring-2 ring-violet-100":"border-violet-100 bg-violet-50"}`}><Wrench size={16} className="text-violet-600"/><strong className="mt-2 block text-xs text-violet-900">{category}</strong><span className="text-[10px] text-violet-700">{items.length} atividade(s)</span></button>)}{!counts.maintenance?<p className="col-span-full rounded-xl border border-dashed p-8 text-center text-sm text-[#718197]">Nenhuma manutenção ativa.</p>:null}</div>{maintenanceCategory?<div className="mt-3 space-y-2 border-t border-violet-100 pt-3">{(maintenanceGroups.find(([category])=>category===maintenanceCategory)?.[1]??[]).map((item)=><article key={item.id} className={`rounded-xl p-3 ${item.editedAt?"border border-amber-300 bg-amber-50":"bg-[#f7f4ff]"}`}><div className="flex items-start justify-between gap-2"><strong className="font-mono text-sm text-violet-950">{item.prefix??"Sem prefixo"} · {item.category}</strong><span className="rounded-full bg-violet-100 px-2 py-1 text-[9px] font-extrabold text-violet-800">{item.status==="completed"?"Encerrado":"Programado"}</span></div><p className="mt-1 whitespace-pre-wrap text-xs font-bold text-[#17324d]">{item.title??maintenanceCategory}</p>{item.editedAt?<p className="mt-1 text-xs font-bold text-amber-800">Alterada · {new Date(item.editedAt).toLocaleString("pt-BR")}</p>:null}<p className="mt-1 line-clamp-2 text-[11px] text-[#718197]">Referente a: {item.description??"Não informado"}</p>{item.spot?<p className="mt-2 text-xs font-bold">Spot: {item.spot}</p>:null}{item.crewRequirement?<p className="mt-1 text-xs">Tripulação necessária: {item.crewRequirement}</p>:null}<p className="mt-2 text-xs">Tripulação designada: {[item.commander,item.copilot].filter(Boolean).map(id=>people.find(p=>p.employeeNumber===id)?.name||id).join(" · ")||"Não informada"}</p>{flights.some(f=>f.id===item.flightId)?<button className="mt-3 rounded-lg bg-violet-700 px-3 py-2 text-sm font-bold text-white" onClick={()=>{const flight=flights.find(f=>f.id===item.flightId);if(flight)onOpenTrail(flight);}}>Abrir no trilho</button>:null}</article>)}</div>:null}</section></div>
 {clientsOpen&&supabase?<ClientManagement supabase={supabase} user="coordination" onClose={()=>setClientsOpen(false)} onError={onError}/>:null}</section>;
}

export function FlightCoordination({supabase,flights,aircraft,people,user,onCreate,onUpdate,onConfirm,onOpenTrail,wavesMode=false,onOpenWaves,onBack}:{supabase?:SupabaseClient|null;flights:CoordinatedFlight[];aircraft:Aircraft[];people:Person[];user:string;onCreate:(flight:CoordinatedFlight)=>Promise<boolean>;onUpdate?:(flight:CoordinatedFlight)=>Promise<boolean>;onConfirm:(id:string)=>void;onOpenTrail:(flight:CoordinatedFlight)=>void;wavesMode?:boolean;onOpenWaves:()=>void;onBack:()=>void}){
 const available=aircraft.filter((item)=>item.available??true);
 const blank=():Draft=>({id:uid(),prefix:available[0]?.prefix??"",date:today(),departure:"08:00",destination:"",duration:"01:30",fuelAmount:"0",fuelUnit:"L",commander:"",copilot:"",flightAttendant:"",repeat:false,weekdays:[],weekdayTimes:{}});
 const [drafts,setDrafts]=useState<Draft[]>([blank()]);
 const [saving,setSaving]=useState(false);
 const [message,setMessage]=useState("");
 const [selectedDate,setSelectedDate]=useState(()=>typeof window!=="undefined"?localStorage.getItem("coordination-planning-date")??today():today());
 const [selectedConfirmations,setSelectedConfirmations]=useState<Set<string>>(()=>new Set());
 const [repeatOpenId,setRepeatOpenId]=useState<string|null>(null); const [editOpenId,setEditOpenId]=useState<string|null>(null);
 const [editAction,setEditAction]=useState<FlightAction>("edit");
 const [platforms,setPlatforms]=useState<PlatformOption[]>([]);
 const [platformSearch,setPlatformSearch]=useState("");
 useEffect(()=>{if(!supabase)return;let active=true;const load=async()=>{const [{data:platformRows},{data:clientRows}]=await Promise.all([supabase.from("client_platforms").select("id,name,client_id").eq("active",true).order("name"),supabase.from("operational_clients").select("id,name").eq("active",true).order("name")]);if(!active)return;const names=new Map(((clientRows??[]) as {id:string;name:string}[]).map((row)=>[row.id,row.name]));setPlatforms(((platformRows??[]) as {id:string;name:string;client_id:string}[]).map((row)=>({id:row.id,name:row.name,clientName:names.get(row.client_id)??""})));};void load();return()=>{active=false;};},[supabase]);
 const filteredPlatforms=useMemo(()=>{const query=platformSearch.trim().toLocaleLowerCase("pt-BR");return platforms.filter((item)=>!query||`${item.name} ${item.clientName}`.toLocaleLowerCase("pt-BR").includes(query));},[platforms,platformSearch]);
 const crew=people.filter((person)=>["commander","copilot","pilot"].includes(person.profile??""));
 const attendants=people.filter((person)=>person.profile==="flight_attendant");
 const groups=useMemo(()=>operationalWaves(flights,selectedDate),[flights,selectedDate]);
 const active=groups.flatMap(group=>group.items);
 const selectedPlanned=active.filter(flight=>flight.planningStatus==="planned"&&selectedConfirmations.has(flight.id));
 function toggleSelection(id:string){setSelectedConfirmations(current=>{const next=new Set(current);if(next.has(id))next.delete(id);else next.add(id);return next;});}
 function confirmSelected(items:CoordinatedFlight[]){items.forEach(flight=>onConfirm(flight.id));setSelectedConfirmations(current=>new Set([...current].filter(id=>!items.some(flight=>flight.id===id))));}

 function update(id:string,patch:Partial<Draft>){setDrafts((items)=>items.map((item)=>item.id===id?{...item,...patch}:item));}
 function duplicateDraft(item:Draft){setDrafts((items)=>[...items,{...item,id:uid(),departure:item.departure}]);}
 function datesFor(item:Draft){if(!item.repeat||!item.weekdays.length)return [{date:item.date,departure:item.departure}];const dates:{date:string;departure:string}[]=[{date:item.date,departure:item.departure}];for(let offset=1;offset<84;offset++){const date=addDays(item.date,offset);const day=new Date(`${date}T12:00:00`).getDay();if(item.weekdays.includes(day))dates.push({date,departure:item.weekdayTimes[day]??item.departure});}return dates;}
 function nextWave(prefix:string,date:string){return Math.max(0,...flights.filter((flight)=>!flight.deletedAt&&Boolean(flight.planningStatus)&&flight.prefix===prefix&&flight.date===date).map((flight)=>flight.wave??1))+1;}
 async function publish(){if(saving)return;const invalid=drafts.some((item)=>{const selected=available.find((plane)=>plane.prefix===item.prefix);return !selected||!item.date||!item.departure||!item.destination.trim()||!item.duration||(item.repeat&&(!item.weekdays.length||item.weekdays.some((day)=>!item.weekdayTimes[day])));});if(invalid){setMessage("Preencha aeronave, destino e horários. Para repetição, escolha os dias e o horário de cada dia. A tripulação pode ser definida depois, em cada voo.");return;}setSaving(true);setMessage("");let created=0;try{const waveCounters=new Map<string,number>();for(const item of drafts){const selected=available.find((plane)=>plane.prefix===item.prefix)!;const recurrenceId=item.repeat?uid():"";for(const occurrence of datesFor(item)){const {date,departure}=occurrence;const at=new Date().toISOString();const key=`${item.prefix}:${date}`;const wave=waveCounters.get(key)??nextWave(item.prefix,date);waveCounters.set(key,wave+1);const saved=await onCreate({id:uid(),prefix:selected.prefix,model:selected.model,base:selected.base,date,departure,destination:item.destination.trim(),spot:item.spot?.trim()||"",duration:clockToDuration(item.duration),fuelAmount:Number(item.fuelAmount)||0,fuelUnit:item.fuelUnit,fuel:"pending",preflight:"pending",hums:"pending",engineStart:"pending",shutdown:"pending",revision:1,acknowledged:{[user]:1},planningStatus:"planned",wave,commander:date===item.date?item.commander:"",copilot:date===item.date?item.copilot:"",flightAttendant:date===item.date&&isS92(selected.model)?item.flightAttendant:"",recurrenceId,recurrenceLabel:recurrenceLabel(item),actionBy:{created:user},history:[{field:"created",value:"Voo programado pela Coordenação",employeeNumber:user,at}],createdBy:user,updatedBy:user});if(saved)created++;}}if(created){setMessage(`${created} voo${created===1?"":"s"} programado${created===1?"":"s"}. Confirme para publicar no Trilho.`);setDrafts([blank()]);}else setMessage("O voo não foi gravado. A conexão será restabelecida automaticamente; tente novamente.");}catch{setMessage("Houve uma oscilação ao programar. Seus campos foram mantidos para tentar novamente.");}finally{setSaving(false);}}
 async function duplicateFlight(flight:CoordinatedFlight){const at=new Date().toISOString();await onCreate({...flight,id:uid(),fuel:"pending",preflight:"pending",hums:"pending",engineStart:"pending",shutdown:"pending",actualEngineStart:null,actualShutdown:null,operationStartedAt:undefined,operationEndedAt:undefined,cancelled:false,cancelledAt:undefined,cancellationReason:undefined,deletedAt:undefined,deletedBy:undefined,recurrenceId:"",recurrenceLabel:"",planningStatus:"planned",wave:(flight.wave??1)+1,revision:1,acknowledged:{[user]:1},commander:"",copilot:"",flightAttendant:"",actionBy:{created:user},history:[{field:"created",value:`Duplicado do voo ${flight.prefix} de ${flight.date}`,employeeNumber:user,at}],createdBy:user,updatedBy:user});}
 function editFlight(flight:CoordinatedFlight,action:FlightAction="edit"){setEditAction(action);setEditOpenId(flight.id);}
 const repeatDraft=drafts.find((item)=>item.id===repeatOpenId);
 function renderFields(item:Draft,change:(patch:Partial<Draft>)=>void,options=available){const selected=options.find((plane)=>plane.prefix===item.prefix);return <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><Field label="Aeronave"><select value={item.prefix} onChange={(event)=>change({prefix:event.target.value,flightAttendant:""})}>{options.map((plane)=><option key={plane.prefix} value={plane.prefix}>{plane.prefix} · {plane.model}</option>)}</select></Field><Field label="Spot (opcional)"><input value={item.spot||""} onChange={(event)=>change({spot:event.target.value})}/></Field><Field label="Data"><input type="date" value={item.date} onChange={(event)=>change({date:event.target.value})}/></Field><Field label="Saída"><input type="time" value={item.departure} onChange={(event)=>change({departure:event.target.value})}/></Field><Field label="Cliente / plataforma"><input list={`coordination-platforms-${item.id}`} value={item.destination} onChange={(event)=>{setPlatformSearch(event.target.value);change({destination:event.target.value})}} placeholder="Digite ou selecione uma plataforma" required/><datalist id={`coordination-platforms-${item.id}`}>{filteredPlatforms.map((platform)=><option key={platform.id} value={platform.name}>{platform.clientName?`${platform.clientName} · `:""}{platform.name}</option>)}</datalist></Field><Field label="Duração"><input type="time" value={item.duration} onChange={(event)=>change({duration:event.target.value})}/></Field><Field label="Comandante"><select value={item.commander} onChange={(event)=>change({commander:event.target.value})}><option value="">Selecione</option>{item.commander&&!crew.some((person)=>person.employeeNumber===item.commander)?<option value={item.commander}>{people.find((person)=>person.employeeNumber===item.commander)?.name??item.commander}</option>:null}{crew.map((person)=><option key={person.employeeNumber} value={person.employeeNumber}>{person.name} · {person.employeeNumber}</option>)}</select></Field><Field label="Copiloto"><select value={item.copilot} onChange={(event)=>change({copilot:event.target.value})}><option value="">Selecione</option>{item.copilot&&!crew.some((person)=>person.employeeNumber===item.copilot)?<option value={item.copilot}>{people.find((person)=>person.employeeNumber===item.copilot)?.name??item.copilot}</option>:null}{crew.map((person)=><option key={person.employeeNumber} value={person.employeeNumber}>{person.name} · {person.employeeNumber}</option>)}</select></Field>{isS92(selected?.model??"")?<Field label="Comissário"><select value={item.flightAttendant} onChange={(event)=>change({flightAttendant:event.target.value})}><option value="">Selecione</option>{item.flightAttendant&&!attendants.some((person)=>person.employeeNumber===item.flightAttendant)?<option value={item.flightAttendant}>{people.find((person)=>person.employeeNumber===item.flightAttendant)?.name??item.flightAttendant}</option>:null}{attendants.map((person)=><option key={person.employeeNumber} value={person.employeeNumber}>{person.name} · {person.employeeNumber}</option>)}</select></Field>:null}<Field label="Abastecimento"><div className="grid grid-cols-[1fr_76px] gap-1"><input type="number" min="0" value={item.fuelAmount} onChange={(event)=>change({fuelAmount:event.target.value})}/><select aria-label="Unidade de abastecimento" value={item.fuelUnit} onChange={(event)=>change({fuelUnit:event.target.value as FuelUnit})}><option>L</option><option>lb</option><option>kg</option></select></div></Field></div>;}
 const editingFlight=flights.find((item)=>item.id===editOpenId&&!item.deletedAt);

 return <section className="space-y-5">{!wavesMode?<><header className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-[.15em] text-[#1769e0]">Planejamento operacional</p><h2 className="text-2xl font-extrabold text-[#17324d]">Coordenação de Voo</h2><p className="text-sm text-[#718197]">Programe em lote e confirme somente quando o voo estiver pronto para aparecer no Trilho comum.</p></div><div className="rounded-xl bg-white px-4 py-3 text-xs font-bold text-[#52677f] shadow-sm"><span className="text-slate-500">{active.filter((item)=>item.planningStatus==="planned"&&!item.cancelled).length} programados</span><span className="mx-2">·</span><span className="text-blue-700">{active.filter((item)=>item.planningStatus!=="planned").length} confirmados</span></div></header>
 <section className="rounded-2xl border border-[#d8e4ef] bg-white p-4 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-extrabold text-[#17324d]">Programar voos</h3><p className="text-xs text-[#718197]">Adicione vários voos ou mantenha uma programação recorrente ativa.</p></div><button onClick={()=>setDrafts((items)=>[...items,blank()])} className="flex min-h-10 items-center gap-2 rounded-xl bg-[#1268d8] px-3 text-xs font-bold text-white"><Plus size={16}/>Adicionar voo</button></div><div className="space-y-3">{drafts.map((item,index)=>{return <article key={item.id} className="rounded-2xl border bg-[#f7faff] p-3"><div className="mb-3 flex items-center justify-between"><strong className="text-sm">Voo {index+1}</strong><div className="flex gap-1"><button onClick={()=>duplicateDraft(item)} title="Duplicar" className="grid h-9 w-9 place-items-center rounded-lg border bg-white text-[#315b86]"><Copy size={15}/></button>{drafts.length>1?<button onClick={()=>setDrafts((items)=>items.filter((draft)=>draft.id!==item.id))} title="Remover" className="grid h-9 w-9 place-items-center rounded-lg border border-red-200 bg-white text-red-600"><Trash2 size={15}/></button>:null}</div></div>{renderFields(item,(patch)=>update(item.id,patch))}<div className="mt-3 rounded-xl bg-white p-3"><button type="button" onClick={()=>setRepeatOpenId(item.id)} className={`flex min-h-11 w-full items-center justify-between rounded-xl border px-3 text-sm font-bold ${item.repeat?"border-blue-300 bg-blue-50 text-blue-800":"border-[#cbd9e7] text-[#315b86]"}`}><span className="flex items-center gap-2"><CalendarDays size={17}/>{item.repeat?"Repetição contínua ativa":"Repetir voo"}</span><span>{item.repeat?"Editar":"Configurar"}</span></button>{item.repeat?<div className="mt-2 flex items-start justify-between gap-2"><p className="text-xs leading-5 text-[#52677f]">{item.weekdays.map((day)=>`${weekdayLabels[day]} às ${item.weekdayTimes[day]}`).join(" · ")}</p><button type="button" onClick={()=>update(item.id,{repeat:false,weekdays:[],weekdayTimes:{}})} className="shrink-0 text-xs font-bold text-red-600">Desativar</button></div>:null}</div></article>})}</div>{message?<p className="mt-3 rounded-xl bg-blue-50 p-3 text-sm font-semibold text-blue-800">{message}</p>:null}<button disabled={saving} onClick={()=>void publish()} className="mt-4 flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#1268d8] font-extrabold text-white disabled:opacity-50"><CalendarDays size={18}/>{saving?"Programando…":`Programar ${drafts.length} voo${drafts.length===1?"":"s"}`}</button></section>
 </>:null}
 {wavesMode?<section aria-label="Página de programação por levas" className="space-y-5 pb-24">
  <header className="flex flex-wrap items-end justify-between gap-3"><div><button onClick={onBack} className="mb-2 min-h-10 text-sm font-bold text-blue-700">← Voltar à Programação</button><h2 className="text-2xl font-extrabold text-[#17324d]">Programação por levas</h2><p className="text-sm text-[#718197]">{active.length} voos ativos · {groups.length} levas. Encerrados e cancelados ficam nas consultas próprias.</p></div><label className="text-sm font-bold">Data<input aria-label="Data da programação por levas" type="date" value={selectedDate} onChange={event=>{setSelectedDate(event.target.value);setSelectedConfirmations(new Set());}} className="ml-2 min-h-11 rounded-xl border bg-white px-3"/></label></header>
  <div className="sticky top-0 z-20 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-blue-200 bg-white p-3 shadow-md"><p className="text-sm font-bold"><span className="text-orange-700">{active.filter(f=>f.planningStatus==="planned").length} programados</span> · <span className="text-blue-700">{active.filter(f=>f.planningStatus!=="planned").length} confirmados</span></p><button disabled={!selectedPlanned.length} onClick={()=>confirmSelected(selectedPlanned)} className="min-h-11 rounded-xl bg-[#1268d8] px-4 text-sm font-bold text-white disabled:opacity-40">Confirmar selecionados ({selectedPlanned.length})</button></div>
  {message?<p role="status" className="rounded-xl bg-blue-50 p-3 text-sm">{message}</p>:null}
  {groups.map(({date,wave,items})=>{const planned=items.filter(f=>f.planningStatus==="planned");const selected=planned.filter(f=>selectedConfirmations.has(f.id));return <section key={`${date}-${wave}`} aria-label={`${wave}ª leva`} className="rounded-2xl border border-[#cbd9e7] border-t-4 border-t-blue-400 bg-white p-4 shadow-sm"><header className="mb-4 flex flex-wrap items-center justify-between gap-3 border-b pb-3"><div><h3 className="text-lg font-extrabold">{wave}ª leva</h3><p className="text-xs text-[#60758c]">{items.length} voos · {planned.length} programados · {items.length-planned.length} confirmados</p></div>{planned.length?<button onClick={()=>setSelectedConfirmations(current=>{const next=new Set(current);planned.forEach(f=>selected.length===planned.length?next.delete(f.id):next.add(f.id));return next;})} className="min-h-11 rounded-xl border px-3 text-sm font-bold">{selected.length===planned.length?"Desmarcar leva":"Selecionar leva"}</button>:null}</header><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">{items.map(flight=><CoordinationCard key={flight.id} flight={flight} people={people} selected={selectedConfirmations.has(flight.id)} onToggleSelected={()=>toggleSelection(flight.id)} onConfirm={()=>onConfirm(flight.id)} onDuplicate={()=>void duplicateFlight(flight)} onEdit={()=>editFlight(flight)} onDelete={()=>editFlight(flight,"delete")} onCancel={()=>editFlight(flight,"cancel")} onOpenTrail={()=>onOpenTrail(flight)}/>)}</div></section>})}
  {!groups.length?<p className="rounded-xl border border-dashed bg-white p-10 text-center text-[#718197]">Nenhum voo ativo nesta data.</p>:null}
 </section>:<WaveSummary groups={groups} date={selectedDate} onDate={setSelectedDate} onOpen={onOpenWaves}/>}

 {repeatDraft?<RepeatDialog item={repeatDraft} onChange={(patch)=>update(repeatDraft.id,patch)} onClose={()=>setRepeatOpenId(null)}/>:null}{editingFlight?<FlightEditDialog key={editingFlight.id} flight={editingFlight} flights={flights} user={user} aircraft={aircraft} onSave={onUpdate} onCreate={onCreate} renderFields={renderFields} initialAction={editAction} onClose={()=>setEditOpenId(null)} onSaved={(date,result)=>{setSelectedDate(date);setMessage(result);setEditOpenId(null);}}/>:null}
 </section>;
}

function coordinationStatus(flight:CoordinatedFlight){
 if(flight.cancelled)return{label:"Cancelado",card:"border-red-500 bg-red-50",badge:"bg-red-100 text-red-800",icon:"text-red-600"};
 if(flight.planningStatus==="planned")return{label:"Programado · não confirmado",card:"border-orange-500 bg-orange-50",badge:"bg-orange-100 text-orange-800",icon:"text-orange-600"};

 if(flight.shutdown==="ok"||flight.actualShutdown)return{label:"Encerrado",card:"border-slate-400 bg-slate-50",badge:"bg-slate-200 text-slate-700",icon:"text-slate-500"};
 if(flight.engineStart==="ok"||flight.actualEngineStart)return{label:"Em voo",card:"border-emerald-500 bg-emerald-50",badge:"bg-emerald-100 text-emerald-800",icon:"text-emerald-600"};
 return{label:"Confirmado · no Trilho",card:"border-blue-500 bg-blue-50",badge:"bg-blue-100 text-blue-800",icon:"text-blue-600"};
}

function CoordinationCard({flight,people,selected,onToggleSelected,onConfirm,onDuplicate,onEdit,onDelete,onCancel,onOpenTrail}:{flight:CoordinatedFlight;people:Person[];selected:boolean;onToggleSelected:()=>void;onConfirm:()=>void;onDuplicate:()=>void;onEdit:()=>void;onDelete:()=>void;onCancel:()=>void;onOpenTrail:()=>void}){
 const status=coordinationStatus(flight);const person=(employee?:string)=>people.find((item)=>item.employeeNumber===employee)?.name??employee??"Não informado";
 return <div className={`rounded-xl border-l-4 p-3 ${status.card}`}><div className="flex items-start justify-between gap-2"><div className="flex items-start gap-2">{flight.planningStatus==="planned"&&!flight.cancelled?<input type="checkbox" checked={selected} onChange={onToggleSelected} aria-label={`Selecionar voo ${flight.prefix} para confirmação`} className="mt-1 h-4 w-4 accent-[#1268d8]"/>:null}<div><strong className="font-mono text-base">{flight.prefix}</strong><p className="text-[10px] text-[#718197]">{flight.date.split("-").reverse().join("/")} · {flight.departure}</p></div></div><Plane size={16} className={status.icon}/></div><p className="mt-1 flex items-center gap-1 text-[10px] font-semibold text-[#52677f]">Destino: {flight.destination||"Não informado"}</p>{flight.spot?<p className="mt-1 text-xs font-bold">Spot: {flight.spot}</p>:null}<span className={`mt-2 inline-block rounded-full px-2 py-1 text-[9px] font-extrabold ${status.badge}`}>{status.label}</span>{flight.commander?<p className="mt-2 truncate text-xs font-semibold">Cmt. {person(flight.commander)}</p>:null}{flight.copilot?<p className="truncate text-[10px] text-[#718197]">Cop. {person(flight.copilot)}</p>:null}{!flight.commander&&!flight.copilot&&!flight.flightAttendant?<p className="mt-2 text-xs text-[#718197]">Tripulação não escalada</p>:null}{flight.flightAttendant?<p className="truncate text-[10px] text-[#718197]">Comiss. {person(flight.flightAttendant)}</p>:null}<p className="mt-1 text-[9px] text-[#8a99a9]">Lançado por mat. {flight.createdBy}</p><div className="mt-3 grid grid-cols-[1fr_auto_auto_auto] gap-1">{flight.cancelled?<button disabled className="rounded-lg bg-red-100 px-2 py-2 text-[10px] font-bold text-red-700">Voo cancelado</button>:flight.planningStatus==="planned"?<button onClick={onConfirm} className="rounded-lg bg-orange-500 px-2 py-2 text-[10px] font-bold text-white">Confirmar este voo</button>:<button onClick={onOpenTrail} className="rounded-lg bg-[#1268d8] px-2 py-2 text-[10px] font-bold text-white">Abrir no Trilho</button>}<button onClick={onEdit} title="Editar voo" className="grid h-8 w-8 place-items-center rounded-lg border bg-white text-[#1268d8]" aria-label="Editar voo"><Edit3 size={13}/></button><button onClick={onDuplicate} title="Duplicar voo" className="grid h-8 w-8 place-items-center rounded-lg border bg-white text-[#315b86]"><Copy size={13}/></button><button onClick={onDelete} title="Excluir voo" className="grid h-8 w-8 place-items-center rounded-lg border border-red-200 bg-white text-red-600"><Trash2 size={13}/></button></div>{flight.planningStatus==="planned"?<button onClick={onOpenTrail} className="mt-2 min-h-10 w-full rounded-lg border text-xs font-bold text-blue-700">Abrir no Trilho</button>:null}<button onClick={onCancel} className="mt-2 min-h-10 w-full rounded-lg border border-red-200 text-xs font-bold text-red-700">Cancelar voo</button></div>;
}

function FlightEditDialog({flight,flights,user,aircraft,onSave,onCreate,renderFields,initialAction,onClose,onSaved}:{
 flight:CoordinatedFlight;flights:CoordinatedFlight[];user:string;aircraft:Aircraft[];
 onSave?: (flight:CoordinatedFlight)=>Promise<boolean>;onCreate:(flight:CoordinatedFlight)=>Promise<boolean>;
 renderFields:(item:Draft,change:(patch:Partial<Draft>)=>void,options:Aircraft[])=>React.ReactNode;
 initialAction:FlightAction;onClose:()=>void;onSaved:(date:string,result:string)=>void;
}){
 const [original]=useState(flight);
 const [item,setItem]=useState(()=>flightToDraft(flight));
 const candidates=editableOccurrences(original,flights);
 const [scope,setScope]=useState<FlightScope>("this");
 const [confirmingScope,setConfirmingScope]=useState(false);
 const [action,setAction]=useState<FlightAction>(initialAction);
 const [reason,setReason]=useState("");
 const recurring=Boolean(recurrenceKey(original));
 const [saving,setSaving]=useState(false);
 const [error,setError]=useState("");
 const pending=useRef<ReturnType<typeof planFlightEdit>|null>(null);
 const [retrying,setRetrying]=useState(false);
 const busy=useRef(false);
 const dialog=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const element=dialog.current;element?.showModal();const overflow=document.body.style.overflow;document.body.style.overflow="hidden";return()=>{element?.close();document.body.style.overflow=overflow;};},[]);
 const options=aircraft.filter((plane)=>plane.available!==false||plane.prefix===original.prefix);
 if(!options.some((plane)=>plane.prefix===original.prefix))options.push({prefix:original.prefix,model:original.model,base:original.base});
 const scheduleChanged=recurrenceLabel(flightToDraft(original))!==recurrenceLabel(item);
 function change(patch:Partial<Draft>){setItem((current)=>({...current,...patch}));setError("");}
 function toggleDay(day:number){change({weekdays:item.weekdays.includes(day)?item.weekdays.filter((value)=>value!==day):[...item.weekdays,day],weekdayTimes:{...item.weekdayTimes,[day]:item.weekdayTimes[day]??item.departure}});}
 async function save(chosenScope?:FlightScope){
  if(busy.current||!onSave)return;
  const effectiveScope=chosenScope??scope;
  if(chosenScope){setScope(chosenScope);setConfirmingScope(false);}
  const plane=options.find((candidate)=>candidate.prefix===item.prefix);
  if(action==="edit"&&(!plane||!item.date||!item.departure||!item.destination.trim()||!item.duration||clockToDuration(item.duration)<=0||!Number.isFinite(Number(item.fuelAmount))||Number(item.fuelAmount)<0||(item.repeat&&(!recurring||effectiveScope==="future")&&(!item.weekdays.length||item.weekdays.some((day)=>!item.weekdayTimes[day]))))){
   setError("Preencha aeronave, data, saída, destino e duração. Para repetir, selecione os dias e horários.");return;
  }
  if(recurring&&!retrying&&!chosenScope){setConfirmingScope(true);return;}
  busy.current=true;setSaving(true);setError("");
  try{
   if(!pending.current){
    if(action!=="edit"){pending.current=planFlightAction(flight,flights,action,effectiveScope,user,reason);}
    else {
    const updated={...flight,prefix:plane!.prefix,model:plane!.model,base:plane!.base,date:item.date,departure:item.departure,destination:item.destination.trim(),spot:item.spot?.trim()||"",duration:clockToDuration(item.duration),fuelAmount:Number(item.fuelAmount),fuelUnit:item.fuelUnit,commander:item.commander,copilot:item.copilot,flightAttendant:isS92(plane!.model)?item.flightAttendant:""};
    pending.current=planFlightEdit(original,updated,item,editableOccurrences(original,flights),flights,user,effectiveScope);
    }
   }
   while(pending.current.length){
    const operation=pending.current[0];
    const saved=await (operation.kind==="create"?onCreate(operation.flight):onSave(operation.flight));
    if(!saved)throw new Error("save_failed");
    pending.current.shift();
   }
   onSaved(action==="edit"?item.date:original.date,action==="delete"?"Voos movidos para a lixeira.":action==="cancel"?"Cancelamento registrado.":"Alterações salvas.");
  }catch{setRetrying(true);setError("Não foi possível concluir o salvamento. Algumas alterações podem já ter sido salvas. Tente novamente para concluir as restantes; seus campos foram mantidos.");}
  finally{busy.current=false;setSaving(false);}
 }
 return <dialog ref={dialog} aria-labelledby="flight-edit-title" onCancel={(event)=>{event.preventDefault();if(!busy.current)onClose();}} className="m-auto max-h-[90dvh] w-[calc(100%-2rem)] max-w-4xl overflow-y-auto rounded-2xl bg-white p-0 text-[#17324d] shadow-2xl backdrop:bg-[#071a30]/60">
  <form onSubmit={(event)=>{event.preventDefault();void save();}}>
   <header className="sticky top-0 z-10 flex items-start justify-between gap-3 border-b border-[#d8e4ef] bg-white p-5"><div><p className="text-xs font-bold uppercase tracking-wider text-[#1769e0]">Configuração do voo</p><h3 id="flight-edit-title" className="mt-1 text-xl font-black">Editar {original.prefix} · {original.date.split("-").reverse().join("/")}</h3><p className="mt-1 text-xs text-[#718197]">{coordinationStatus(flight).label}</p></div><button type="button" disabled={saving} onClick={onClose} aria-label="Fechar edição" className="grid h-10 w-10 shrink-0 place-items-center rounded-xl hover:bg-blue-50 disabled:opacity-40"><X size={20}/></button></header>
   <fieldset disabled={saving||retrying} className="space-y-5 p-5 disabled:opacity-60">
    {action==="edit"?<>
    {renderFields(item,change,options)}
    <p className="text-xs leading-5 text-[#718197]">A tripulação é definida individualmente para este voo. As novas repetições ficam sem tripulação até a coordenação preencher cada escala.</p>
    <section className="rounded-xl border border-[#d8e4ef] bg-[#f7faff] p-4"><label className="flex items-center gap-3 text-sm font-bold"><input type="checkbox" checked={item.repeat} onChange={(event)=>change({repeat:event.target.checked})} className="h-5 w-5 accent-[#1268d8]"/>Repetir voo</label>
     <p className="mt-2 text-xs text-[#718197]">{item.repeat?"Escolha os dias e o horário de cada repetição. Programação para as próximas 12 semanas.":"Repetição desativada. O voo selecionado será mantido."}</p>
     {item.repeat?<div className="mt-3 grid gap-2 sm:grid-cols-2">{weekdayLabels.map((label,day)=><div key={day} className={`flex items-center justify-between gap-3 rounded-xl border p-2 ${item.weekdays.includes(day)?"border-blue-300 bg-blue-50":"border-[#d8e4ef] bg-white"}`}><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={item.weekdays.includes(day)} onChange={()=>toggleDay(day)} className="h-4 w-4 accent-[#1268d8]"/>{label}</label><input type="time" aria-label={`Horário de ${label}`} disabled={!item.weekdays.includes(day)} value={item.weekdayTimes[day]??item.departure} onChange={(event)=>change({weekdayTimes:{...item.weekdayTimes,[day]:event.target.value}})} className="h-10 rounded-lg border bg-white px-2 disabled:opacity-40"/></div>)}</div>:null}
    </section>
    {scheduleChanged?<p className="text-xs leading-5 text-[#52677f]">{item.repeat?"As datas que continuarem na programação manterão seus voos. Novos dias terão novas ocorrências, ainda não confirmadas.":"Para desativar a repetição e remover as ocorrências futuras, escolha este e todos os futuros ao salvar."}</p>:null}
    </>:<section className={action==="delete"?"rounded-xl border border-red-200 bg-red-50 p-4":"rounded-xl border border-amber-200 bg-amber-50 p-4"}><h4 className="font-bold">{action==="delete"?"Excluir voo":"Cancelar voo"}</h4><p className="mt-2 text-sm">{action==="delete"? "Os voos escolhidos serão movidos para a lixeira." : "Os voos escolhidos continuarão no planejamento com o status Cancelado."}</p>{action==="cancel"?<label className="mt-4 block text-sm font-bold">Motivo do cancelamento (opcional)<textarea value={reason} onChange={(event)=>setReason(event.target.value)} className="mt-2 min-h-20 w-full rounded-lg border bg-white p-2"/></label>:null}</section>}
    {recurring&&candidates.length>0?<details className="rounded-xl border p-3"><summary className="cursor-pointer text-sm font-bold">Ver os {candidates.length} próximos voos da repetição</summary><ul className="mt-2 max-h-40 space-y-1 overflow-y-auto text-xs">{candidates.map((candidate)=><li key={candidate.id}>{candidate.prefix} · {candidate.date.split("-").reverse().join("/")} · {candidate.departure} · {candidate.destination||"Sem destino"}</li>)}</ul></details>:null}
   </fieldset>
   <footer className="sticky bottom-0 border-t border-[#d8e4ef] bg-white p-4">{error?<p role="alert" className="mb-3 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>:null}<div className="flex flex-wrap justify-end gap-2">{action==="edit"?<><button type="button" disabled={saving||retrying} onClick={()=>setAction("delete")} className="mr-auto rounded-xl border border-red-200 px-3 py-2 text-sm font-bold text-red-600 disabled:opacity-40">Excluir voo</button><button type="button" disabled={saving||retrying||Boolean(flight.cancelled)} onClick={()=>setAction("cancel")} className="rounded-xl border border-amber-300 px-3 py-2 text-sm font-bold text-amber-800 disabled:opacity-40">Cancelar voo</button></>:<button type="button" disabled={saving||retrying} onClick={()=>setAction("edit")} className="mr-auto rounded-xl border px-3 py-2 text-sm font-bold">Voltar à edição</button>}<button type="button" disabled={saving} onClick={onClose} className="rounded-xl border border-[#cbd9e7] px-4 py-2 text-sm font-bold disabled:opacity-40">Fechar</button><button type="submit" disabled={saving||!onSave} className={"rounded-xl px-4 py-3 text-sm font-bold text-white disabled:opacity-40 "+(action==="delete"?"bg-red-600":action==="cancel"?"bg-amber-700":"bg-[#1268d8]")}>{saving?"Salvando…":retrying?"Tentar novamente":action==="delete"?"Confirmar exclusão":action==="cancel"?"Confirmar cancelamento":"Salvar alterações"}</button></div></footer>
  </form>
  {confirmingScope?<FlightScopeConfirmation action={action} futureCount={candidates.length} scheduleChanged={scheduleChanged} onBack={()=>setConfirmingScope(false)} onChoose={(chosen)=>void save(chosen)}/>:null}
 </dialog>;
}

function FlightScopeConfirmation({action,futureCount,scheduleChanged,onBack,onChoose}:{action:FlightAction;futureCount:number;scheduleChanged:boolean;onBack:()=>void;onChoose:(scope:FlightScope)=>void}){
 const dialog=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const element=dialog.current;element?.showModal();return()=>element?.close();},[]);
 const verb=action==="delete"?"Excluir":action==="cancel"?"Cancelar":"Alterar";
 return <dialog ref={dialog} aria-labelledby="flight-scope-title" onCancel={(event)=>{event.preventDefault();onBack();}} className="m-auto max-h-[90dvh] w-[calc(100%-2rem)] max-w-lg overflow-y-auto rounded-2xl bg-white p-5 text-[#17324d] shadow-2xl backdrop:bg-[#071a30]/60">
  <h3 id="flight-scope-title" className="text-xl font-extrabold">{verb} quais voos?</h3>
  <p className="mt-3 text-sm">Este voo faz parte de uma repetição. Escolha onde aplicar {action==="delete"?"a exclusão":action==="cancel"?"o cancelamento":"as alterações"}.</p>
  <div className="mt-5 grid gap-3">
   <button type="button" onClick={()=>onChoose("this")} className="rounded-xl border border-[#1268d8] p-4 text-left text-[#1268d8]"><strong className="block">Somente este voo</strong><span className="mt-1 block text-xs">Os próximos voos mantêm a configuração atual.</span></button>
   <button type="button" onClick={()=>onChoose("future")} className="rounded-xl border border-[#1268d8] bg-blue-50 p-4 text-left text-[#1268d8]"><strong className="block">Este e todos os futuros da repetição</strong><span className="mt-1 block text-xs">Inclui {futureCount} próximo(s) voo(s) elegível(is) já programado(s).</span></button>
  </div>
  <p className="mt-4 text-xs leading-5 text-[#52677f]">Voos anteriores, iniciados, encerrados ou já cancelados são preservados. A tripulação continua sendo definida individualmente em cada voo.</p>
  {action==="edit"&&scheduleChanged?<p className="mt-2 text-xs leading-5 text-[#52677f]">Mudanças nos dias ou na configuração da repetição só serão aplicadas ao escolher este e todos os futuros.</p>:null}
  <button type="button" autoFocus onClick={onBack} className="mt-5 min-h-11 w-full rounded-xl border px-4 py-2 text-sm font-bold">Voltar sem salvar</button>
 </dialog>;
}

function RepeatDialog({item,onChange,onClose}:{item:Draft;onChange:(patch:Partial<Draft>)=>void;onClose:()=>void}){
 const valid=item.weekdays.length>0&&item.weekdays.every((day)=>Boolean(item.weekdayTimes[day]));
 function toggle(day:number){const selected=item.weekdays.includes(day);onChange({weekdays:selected?item.weekdays.filter((value)=>value!==day):[...item.weekdays,day],weekdayTimes:selected?item.weekdayTimes:{...item.weekdayTimes,[day]:item.weekdayTimes[day]??item.departure}});}
 return <div className="fixed inset-0 z-[80] grid place-items-end bg-[#071a30]/60 backdrop-blur-sm sm:place-items-center sm:p-4" onMouseDown={(event)=>{if(event.target===event.currentTarget)onClose();}}><section role="dialog" aria-modal="true" aria-label="Configurar repetição do voo" className="max-h-[90dvh] w-full overflow-y-auto rounded-t-2xl bg-white p-4 shadow-2xl sm:max-w-lg sm:rounded-2xl"><header className="mb-4 flex items-start justify-between"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#1769e0]">Programação contínua</p><h3 className="mt-1 text-xl font-extrabold text-[#17324d]">Repetir voo</h3><p className="mt-1 text-xs leading-5 text-[#718197]">Escolha os dias e horários. A programação continuará ativa enquanto você a mantiver.</p></div><button onClick={onClose} aria-label="Fechar" className="grid h-10 w-10 place-items-center rounded-xl hover:bg-[#edf4fb]"><X size={18}/></button></header><div className="space-y-2">{weekdayLabels.map((label,day)=>{const selected=item.weekdays.includes(day);return <div key={label} className={`grid grid-cols-[1fr_130px] items-center gap-3 rounded-xl border p-3 ${selected?"border-blue-300 bg-blue-50":"bg-[#f6f8fa]"}`}><label className="flex items-center gap-3 text-sm font-bold text-[#315b86]"><input type="checkbox" checked={selected} onChange={()=>toggle(day)} className="h-5 w-5 accent-[#1268d8]"/>{label}</label><input aria-label={`Horário de ${label}`} type="time" disabled={!selected} value={item.weekdayTimes[day]??item.departure} onChange={(event)=>onChange({weekdayTimes:{...item.weekdayTimes,[day]:event.target.value}})} className="h-10 rounded-lg border bg-white px-2 disabled:opacity-40"/></div>})}</div><footer className="mt-5 flex gap-2"><button onClick={()=>{onChange({repeat:false,weekdays:[],weekdayTimes:{}});onClose();}} className="min-h-11 flex-1 rounded-xl border border-red-200 font-bold text-red-600">Desativar repetição</button><button disabled={!valid} onClick={()=>{onChange({repeat:true});onClose();}} className="min-h-11 flex-1 rounded-xl bg-[#1268d8] font-bold text-white disabled:opacity-40">Manter repetindo</button></footer></section></div>;
}

function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="text-[11px] font-bold text-[#52677f]">{label}<div className="mt-1 [&_input]:h-10 [&_input]:w-full [&_input]:rounded-lg [&_input]:border [&_input]:px-2 [&_select]:h-10 [&_select]:w-full [&_select]:rounded-lg [&_select]:border [&_select]:bg-white [&_select]:px-2 [&_select]:text-xs">{children}</div></label>;}

























function WaveSummary({groups,date,onDate,onOpen}:{groups:{wave:number;items:CoordinatedFlight[]}[];date:string;onDate:(date:string)=>void;onOpen:()=>void}){
 return <section className="rounded-2xl border border-[#d9e4ef] bg-white p-4 shadow-sm"><header className="flex flex-wrap items-center justify-between gap-3"><h3 className="font-extrabold text-[#17324d]">Programação por levas</h3><input aria-label="Data do resumo das levas" type="date" value={date} onChange={event=>onDate(event.target.value)} className="min-h-11 rounded-xl border px-3 text-sm"/></header><p className="mt-2 text-sm text-[#718197]">{groups.reduce((total,g)=>total+g.items.length,0)} voos ativos em {groups.length} levas</p><div className="my-3 flex flex-wrap gap-2">{groups.map(group=><button key={group.wave} onClick={onOpen} className="rounded-xl bg-blue-50 px-3 py-2 text-left text-xs"><strong>{group.wave}ª leva · {group.items.length} voos</strong><span className="mt-1 block text-orange-700">{group.items.filter(f=>f.planningStatus==="planned").length} programados · {group.items.filter(f=>f.planningStatus!=="planned").length} confirmados</span></button>)}</div><button onClick={onOpen} className="min-h-11 w-full rounded-xl bg-[#1268d8] px-4 text-sm font-extrabold text-white">Abrir programação por levas</button></section>;
}
